  "plans.priceNote": "Essentials ماهانه 14.99 دلار به‌علاوه مالیات‌های قابل اعمال، در صورت وجود، است. Business ماهانه 29.99 دلار به‌علاوه مالیات‌های قابل اعمال، در صورت وجود، است. هر مالیات لازم در هنگام پرداخت ارائه‌دهنده تعیین می‌شود و باید در مجموع نهایی پیش از پرداخت ظاهر شود. این صفحه مقایسه، برآورد مالیات یا اجازه پرداخت نیست.",
  "plans.mobilePriceNote": "طرح فقط موبایل 4.99 دلار در ماه با قیمت پایه مورد نظر در آمریکا است. App Store یا Google Play قیمت واقعی اشتراک محلی و هر مالیات قابل اعمال را پیش از خرید نشان می‌دهد. سهمیه محصول، سایت و کارکنان آن در زمان عرضه، جدا از رده‌های وب‌سایت، تعیین می‌شود.",
  "plans.planChangeNote": "تغییر طرح وب‌سایت باید توسط ارائه‌دهنده صورت‌حساب تأیید شود. قیمت جدید، تاریخ اجرا و هر مبلغ تناسبی پیش از اجازه تغییر توضیح داده خواهد شد. ارتقا نباید اشتراک دومی ایجاد کند.",
