  "billing.cancel.appStoreNote": "اگر زمانی از طریق Google Play یا Apple App Store مشترک شوید، ممکن است لازم باشد آن را از طریق تنظیمات اشتراک آن فروشگاه لغو کنید. این گفتگو نمی‌تواند صورت‌حساب فروشگاه برنامه را متوقف کند. حذف نصب برنامه یا حذف حساب StockHaven شما اشتراک فروشگاه را لغو نمی‌کند.",
