  "exports.eyebrow": "داده‌ها",
  "exports.title": "صادرات و پشتیبان‌گیری",
  "exports.subtitleStart": "دانلودها همیشه محدود به",
  "exports.subtitleRest": " هستند. هر فایل با نام کسب‌وکار و تاریخ ساخت آن برچسب‌گذاری شده است.",
  "exports.createBusinessFirst": "ابتدا یک کسب‌وکار بسازید — صادرات متعلق به کسب‌وکار است، نه برنامه.",
  "exports.lockedTitle": "صادرات CSV و Excel یک ویژگی Business است",
  "exports.lockedDesc": "فضای کاری شما روی طرح Essentials است. Business صادرات CSV و Excel، ارزش‌گذاری موجودی، محصولات و کارکنان نامحدود، تأمین‌کنندگان، خرید و باندل‌ها را اضافه می‌کند.",
  "exports.seeBusiness": "مشاهده آنچه Business شامل می‌شود",
  "exports.whatTheseAre": "این فایل‌ها چه هستند",
  "exports.about1": "هر مجموعه داده به‌صورت CSV یا کتاب کار واقعی Excel (.xlsx) ارائه می‌شود — کتاب کار کامل موجودی فقط Excel است، با یک برگه برای هر مجموعه داده. فایل‌های CSV در Excel، Numbers، Google Sheets و بیشتر برنامه‌های موجودی باز می‌شوند. متن UTF-8، ویرگول‌های نقل‌قولی، شکست خط در یادداشت‌ها و صفرهای ابتدایی در کدها همگی حفظ می‌شوند و سلول‌هایی که مانند فرمول شروع می‌شوند خنثی می‌شوند تا صفحه‌گسترده آن‌ها را به‌عنوان متن باز کند.",
  "exports.about2": "در فایل‌های Excel، SKUها، UPCها، ISBNها و بارکدها سلول‌های متنی هستند — هرگز نماد علمی و هرگز صفرهای بریده‌شده نیستند — با عرض ستون، فیلترهای سربرگ و قالب‌های ارز یا مقدار اعمال‌شده. کتاب کار کامل موجودی محصولات، سطوح موجودی، مکان‌ها و جابه‌جایی‌ها را روی برگه‌های جداگانه نگه می‌دارد.",
  "exports.about3": "صادرات‌های بسیار بزرگ در 20,000 ردیف برای هر مجموعه داده متوقف می‌شوند — وقتی این اتفاق می‌افتد نام فایل آن را می‌گوید (truncated-20000)، بنابراین فایل جزئی هرگز به‌عنوان کامل جا نمی‌زند.",
  "exports.about4": "پشتیبان تصویری از داده‌های شما است، نه بازیابی با یک کلیک. بازیابی آن کاری دستی و بررسی‌اول است، بنابراین فایل را امن نگه دارید — هنوز هیچ‌چیز در برنامه نمی‌تواند کسب‌وکار حذف‌شده را از آن بازسازی کند. کد برنامه و پشتیبان‌های پلتفرم Base44 جدا از این فایل‌ها انجام می‌شوند.",
  "exports.about5": "عکس‌ها و پیوست‌ها به‌عنوان پیوندهای ذخیره‌شده آن‌ها فهرست می‌شوند — خود فایل‌های تصویری در دانلود بسته‌بندی نمی‌شوند.",
  "exports.backupTitle": "پشتیبان کامل",
  "exports.backupDesc": "یک فایل با محصولات، مکان‌ها، سطوح موجودی، دفتر کامل جابه‌جایی، تأمین‌کنندگان، خرید، سفارش‌ها، بازگشت‌ها، شمارش‌ها و فهرست‌های این کسب‌وکار — به‌علاوه تنظیمات نمایه آن. آن را جایی نگه دارید که تحت کنترل شما باشد.",
  "exports.backupIncludes1": "محصولات، کدها، هزینه‌ها و یادداشت‌ها",
