  "valuation.footnote": "ارزش هزینه از هزینه واحد فعلی هر محصول استفاده می‌کند، بنابراین دریافت با قیمت جدید کل قفسه را دوباره ارزش‌گذاری می‌کند. واحدهای نگه‌داشته‌شده هنوز در اینجا شمرده می‌شوند — آن‌ها موجود هستند، فقط به سفارشی وعده داده شده‌اند. پول گمشده هرگز به‌عنوان صفر در نظر گرفته نمی‌شود؛ فیلدی را تا زمانی که رقم مشخص شود خالی بگذارید.",
