  "settings.cancelSubscription": "لغو اشتراک",
  "settings.cancelTerms.appleLink": "دستورالعمل لغو Apple",
  "settings.cancelTerms.googlePlayLink": "دستورالعمل لغو Google Play",
  "settings.cancelTerms.graceTitle": "پس از پایان دوره پرداخت‌شده شما — مهلت 15 روزه، سپس حذف:",
  "settings.cancelTerms.intro": "این‌ها شرایط اشتراک‌های پولی Luminous StockHaven هستند. صورت‌حساب اشتراک وب‌سایت از طریق Stripe است. می‌توانید اشتراک خود را هر زمان با دکمه لغو اشتراک زیر خودتان لغو کنید — نیازی به تأیید کارکنان نیست. درخواست‌های لغو و بازپرداخت همچنین می‌توانند از طریق تماس رسمی پشتیبانی مشتری، theluminousbookshop@outlook.com، انجام شوند.",
  "settings.cancelTerms.noApprovalBody": "می‌توانید اشتراک خود را هر زمان خودتان لغو کنید. نیازی به تأیید کارکنان نیست. تمدیدهای آینده فقط پس از تأیید لغو توسط ارائه‌دهنده صورت‌حساب متوقف می‌شوند.",
  "settings.cancelTerms.noApprovalTitle": "لغو بدون تأیید:",
  "settings.cancelTerms.paymentBody": "برای دوره‌های آزمایشی پولی، دوره آزمایشی هفت‌روزه نیازمند روش پرداخت هنگام ثبت‌نام است. مگر اینکه ظرف مهلت لغو دوره آزمایشی قابل اعمال لغو شود، طرح ماهانه انتخاب‌شده پس از دوره آزمایشی به‌طور خودکار هزینه خواهد شد. قیمت، تاریخ اولین صورت‌حساب و مهلت لغو خاص ارائه‌دهنده باید هنگام ثبت‌نام نشان داده شود. صورت‌حساب دوره آزمایشی از طریق Stripe است.",
  "settings.cancelTerms.paymentTitle": "روش پرداخت و تمدید خودکار:",
  "settings.cancelTerms.remainingBody": "اگر از قبل برای دوره صورت‌حساب پرداخت کرده‌اید، می‌توانید دسترسی را تا آن تاریخ پرداخت‌شده تأییدشده حفظ کنید. پایان زودتر نیازمند تأیید مناسب ارائه‌دهنده و هر رسیدگی بازپرداخت قابل اعمال است. دسترسی دوره آزمایشی رایگان طبق تاریخ پایان دوره آزمایشی تأییدشده توسط ارائه‌دهنده پایان می‌یابد.",
  "settings.cancelTerms.remainingTitle": "دسترسی باقی‌مانده:",
  "settings.cancelTerms.storesBody": "اگر زمانی از طریق Google Play یا Apple App Store مشترک شوید، اشتراک شما توسط آن فروشگاه صورت‌حساب و مدیریت می‌شود. ممکن است لازم باشد آن را مستقیماً در بخش اشتراک‌های همان حساب Google یا Apple که برای اشتراک استفاده شده است لغو کنید. لغو اشتراک وب‌سایت جداگانه، حذف نصب این برنامه، یا درخواست حذف حساب Luminous StockHaven به‌طور خودکار اشتراک صورت‌حساب‌شده توسط فروشگاه را لغو نمی‌کند. رسید خرید خود را بررسی کنید تا تأیید کنید چه کسی از شما صورت‌حساب می‌گیرد.",
  "settings.cancelTerms.storesTitle": "اشتراک‌های Google Play و Apple App Store (اگر زمانی از طریق فروشگاه مشترک شوید):",
  "settings.cancelTerms.title": "شرایط و ضوابط لغو",
  "settings.cancelTerms.trialBody": "دوره آزمایشی هفت‌روزه فقط یک‌بار برای هر مشتری واجد شرایط قابل استفاده است. لغو دوره آزمایشی یا اشتراک دوره آزمایشی دیگری اعطا نمی‌کند؛ مشتریان بازگشتی باید اشتراک پولی انتخاب کنند.",
  "settings.cancelTerms.trialTitle": "یک دوره آزمایشی رایگان:",
  "settings.canceled.endsOn": "این اشتراک لغو شده است و در {date} پایان می‌یابد. تا آن زمان دسترسی کامل را حفظ می‌کنید.",
  "settings.delete.checking": "در حال بررسی درخواست حذف موجود…",
  "settings.delete.description": "درخواست حذف حساب ورود Luminous StockHaven خود را بدهید.",
  "settings.delete.dialogDescription": "این درخواست بررسی حذف حساب را می‌دهد. ورود یا موجودی شما را بلافاصله حذف نمی‌کند و هیچ اشتراک Stripe را لغو نمی‌کند. {word} را تایپ کنید تا تأیید کنید می‌خواهید درخواست را ارسال کنید.",
  "settings.delete.dialogTitle": "درخواست حذف حساب",
  "settings.delete.enterDelete": "برای تأیید {word} را وارد کنید",
  "settings.delete.exportFirst": "اگر نیاز دارید سوابق خود را نگه دارید، ابتدا موجودی خود را صادر کنید.",
  "settings.delete.intro": "ارسال درخواست حساب، کسب‌وکارها یا موجودی شما را بلافاصله حذف نمی‌کند. درخواست‌ها جدا بررسی می‌شوند پیش از اینکه حذف کامل شود. این درخواست اشتراک Stripe را لغو نمی‌کند یا صورت‌حساب آینده را متوقف نمی‌کند؛ لغو اشتراک باید جدا از طریق ارائه‌دهنده صورت‌حساب انجام شود.",
